+  if (!emailInput.checkValidity()) {
+    emailInput.reportValidity();
+    return;
+  }
+
+  cartStatus.textContent = "Thanks for joining North & Thread membership. Check your inbox for early access updates.";
+  newsletterForm.reset();
+});
