+const navToggle = document.querySelector(".nav-toggle");
+const primaryNav = document.querySelector("#primary-navigation");
+const cartCount = document.querySelector(".cart-count");
+const cartStatus = document.querySelector("#cart-status");
+const addToBagButtons = document.querySelectorAll("[data-product]");
+const newsletterForm = document.querySelector(".newsletter-form");
+
+let bagCount = 0;
+
+navToggle.addEventListener("click", () => {
+  const isExpanded = navToggle.getAttribute("aria-expanded") === "true";
+  navToggle.setAttribute("aria-expanded", String(!isExpanded));
+  primaryNav.toggleAttribute("data-collapsed", isExpanded);
+});
+
+primaryNav.addEventListener("click", (event) => {
+  if (event.target instanceof HTMLAnchorElement && window.matchMedia("(max-width: 920px)").matches) {
+    navToggle.setAttribute("aria-expanded", "false");
+    primaryNav.setAttribute("data-collapsed", "");
+  }
+});
+
+addToBagButtons.forEach((button) => {
+  const productName = button.dataset.product;
+  button.setAttribute("aria-label", `Add to bag: ${productName}`);
+
+  button.addEventListener("click", () => {
+    bagCount += 1;
+    cartCount.textContent = String(bagCount);
+    cartStatus.textContent = `${productName} added to your shopping bag. ${bagCount} ${bagCount === 1 ? "item" : "items"} in bag.`;
+  });
+});
+
+newsletterForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+  const emailInput = newsletterForm.querySelector("#email");
+
+  if (!emailInput.checkValidity()) {
+    emailInput.reportValidity();
+    return;
+  }
+
+  cartStatus.textContent = "Thanks for joining North & Thread membership. Check your inbox for early access updates.";
+  newsletterForm.reset();
+});
+

')

