  --radius-md: 22px;
  --radius-sm: 14px;
  --max-width: 1180px;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background:
    radial-gradient(circle at top left, rgba(234, 214, 200, 0.85), transparent 34rem),
    linear-gradient(180deg, #fbf7f0 0%, var(--bg) 52%, #efe7dc 100%);
  color: var(--ink);
  line-height: 1.5;
}

a {
  color: inherit;
}

img,
svg {
  max-width: 100%;
}

button,
input {
  font: inherit;
}

:focus-visible {
  outline: 3px solid #1d4ed8;
  outline-offset: 4px;
}

.skip-link {
  position: absolute;
  left: 1rem;
  top: 1rem;
  z-index: 20;
  transform: translateY(-140%);
  border-radius: 999px;
  background: var(--ink);
  color: #fff;
  padding: 0.75rem 1rem;
  font-weight: 800;
  text-decoration: none;
  transition: transform 160ms ease;
}

.skip-link:focus {
  transform: translateY(0);
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  border-bottom: 1px solid rgba(216, 204, 192, 0.78);
  background: rgba(255, 250, 243, 0.9);
  backdrop-filter: blur(18px);
}

.header-inner,
main,
.site-footer {
  width: min(calc(100% - 2rem), var(--max-width));
  margin-inline: auto;
}

.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1.5rem;
  min-height: 78px;
}

.brand,
.cart-link {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  font-weight: 850;
  text-decoration: none;
}

.brand-mark {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 50%;
  background: var(--ink);
  color: #fff;
  font-size: 0.82rem;
  letter-spacing: 0.04em;
}

.primary-nav ul,
.site-footer ul,
.product-grid {
  padding: 0;
  margin: 0;
  list-style: none;
}

.primary-nav ul {
  display: flex;
  justify-content: center;
  gap: clamp(1rem, 3vw, 2rem);
}

.primary-nav a {
  border-radius: 999px;
  color: var(--muted);
  font-weight: 750;
  text-decoration: none;
}

.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
  color: var(--ink);
  text-decoration: underline;
  text-decoration-thickness: 0.16em;
  text-underline-offset: 0.4em;
}

.cart-count {
  display: grid;
  min-width: 1.7rem;
  min-height: 1.7rem;
  place-items: center;
  border-radius: 999px;
  background: var(--accent);
  color: #fff;
  font-size: 0.85rem;
}

.nav-toggle {
  display: none;
}

main {
  padding-block: clamp(2rem, 5vw, 4.5rem);
}

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(280px, 0.72fr);
  gap: clamp(1.25rem, 4vw, 3rem);
  align-items: stretch;
  min-height: 560px;
}

.hero > *,
.newsletter > * {
  min-width: 0;
}

.hero-copy,
.hero-panel,
.deal-card,
