    radial-gradient(circle at 50% 45%, #d9e0c9 0 4.5rem, transparent 4.6rem),
    linear-gradient(145deg, #526453, #9eb186);
}

.product-art-blue {
  background:
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.2) 0 10px, transparent 10px 20px),
    linear-gradient(145deg, #29384d, #7c99a5);
}

.product-name {
  display: block;
  padding-inline: 0.25rem;
  font-size: 1.08rem;
  font-weight: 850;
}

.product-meta,
.product-price {
  padding-inline: 0.25rem;
}

.product-meta {
  margin: 0.25rem 0 0.65rem;
  color: var(--muted);
}

.product-price {
  margin-bottom: 1rem;
  font-weight: 900;
}

.deal-grid,
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
}

.deal-card {
  padding: clamp(1.35rem, 3vw, 2rem);
  background: var(--surface);
}

.deal-card h3,
.story-card h3 {
  font-size: clamp(1.35rem, 2.5vw, 2rem);
  line-height: 1.08;
  letter-spacing: -0.035em;
}

.deal-card p:not(.deal-label),
.story-card p:not(.story-category),
.newsletter p {
  color: var(--muted);
}

.deal-card-dark {
  background:
    radial-gradient(circle at top right, rgba(255, 255, 255, 0.18), transparent 12rem),
    var(--ink);
  color: #fff;
}

.deal-card-dark .deal-label,
.deal-card-dark p:not(.deal-label) {
  color: #f5dfce;
}

.story-card {
  display: grid;
  gap: 1rem;
  border-bottom: 1px solid var(--border);
  padding-bottom: 1.25rem;
}

.story-card-large {
  grid-column: span 2;
}

.story-card h3 a {
  text-decoration-thickness: 0.08em;
  text-underline-offset: 0.18em;
}

.story-image-linen {
  background: linear-gradient(145deg, #c99664, #f3ddc2);
}

.story-image-home {
  background: linear-gradient(145deg, #50604d, #d8cfb5);
}

.story-image-maker {
  background: linear-gradient(145deg, #7c6550, #ded1c3);
}

.newsletter {
  display: grid;
  grid-template-columns: 1fr minmax(280px, 0.85fr);
  gap: clamp(1.25rem, 4vw, 3rem);
  align-items: center;
  margin-top: clamp(3rem, 7vw, 6rem);
  padding: clamp(1.5rem, 5vw, 3rem);
  background: var(--surface-strong);
}

.newsletter-form label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: 850;
}

.newsletter-form input {
  flex: 1 1 14rem;
  min-height: 50px;
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: #fff;
  color: var(--ink);
  padding: 0.8rem 1rem;
}

.newsletter-form input::placeholder {
  color: #756b62;
}

.newsletter-form p {
  margin: 0.75rem 0 0;
  font-size: 0.95rem;
}

.status-message {
  margin: 1rem 0 0;
}

.site-footer {
  display: flex;
  justify-content: space-between;
  gap: 2rem;
  border-top: 1px solid var(--border);
  padding-block: 2rem 3rem;
}

.footer-brand {
  margin-bottom: 0.35rem;
  font-weight: 900;
}

.site-footer p {
  max-width: 32rem;
  color: var(--muted);
}

.site-footer ul {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.8rem 1.2rem;
}

.site-footer a {
  color: var(--muted);
  font-weight: 750;
  text-decoration-thickness: 0.08em;
  text-underline-offset: 0.25em;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

@media (forced-colors: active) {
  .site-header,
  .hero-copy,
  .hero-panel,
  .deal-card,
  .newsletter,
  .product-card {
    border: 1px solid CanvasText;
    box-shadow: none;
  }

  .brand-mark,
  .cart-count,
  .button,
  .product-art,
  .story-image {
    forced-color-adjust: none;
  }
}

@media (max-width: 920px) {
  .header-inner {
    grid-template-columns: auto auto auto;
    justify-content: space-between;
  }

  .nav-toggle {
    display: inline-flex;
    align-items: center;
    gap: 0.55rem;
    min-height: 44px;
    border: 1px solid var(--border);
    border-radius: 999px;
    background: #fff;
    color: var(--ink);
    padding: 0.55rem 0.85rem;
    font-weight: 850;
  }

  .nav-toggle-lines,
  .nav-toggle-lines::before,
  .nav-toggle-lines::after {
    display: block;
    width: 18px;
    height: 2px;
    border-radius: 999px;
    background: currentColor;
  }

  .nav-toggle-lines {
    position: relative;
  }

  .nav-toggle-lines::before,
  .nav-toggle-lines::after {
    position: absolute;
    content: "";
    left: 0;
  }

  .nav-toggle-lines::before {
    top: -6px;
  }

  .nav-toggle-lines::after {
    top: 6px;
  }

  .primary-nav {
    grid-column: 1 / -1;
    width: 100%;
  }

  .primary-nav[data-collapsed] {
    display: none;
  }

  .primary-nav ul {
    flex-direction: column;
    align-items: stretch;
    padding: 0 0 1rem;
  }

  .primary-nav a {
    display: block;
    padding: 0.65rem 0;
  }

  .hero,
  .newsletter {
    grid-template-columns: 1fr;
  }

  .product-grid,
  .deal-grid,
  .editorial-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .story-card-large {
    grid-column: span 2;
  }
}

@media (max-width: 640px) {
  .header-inner,
  main,
  .site-footer {
    width: min(calc(100% - 1rem), var(--max-width));
  }

  .header-inner {
    gap: 0.75rem;
    min-height: 68px;
  }

  .brand span:not(.brand-mark),
  .cart-link {
    font-size: 0.92rem;
  }

  .hero {
    min-height: auto;
  }

  .hero-copy,
  .hero-panel,
  .deal-card,
  .newsletter {
    border-radius: 24px;
  }

  h1 {
    font-size: clamp(2.6rem, 18vw, 4.6rem);
  }

  .section-heading,
  .site-footer {
    align-items: flex-start;
    flex-direction: column;
  }

  .product-grid,
  .deal-grid,
  .editorial-grid,
  .story-card-large {
    grid-template-columns: 1fr;
    grid-column: auto;
  }

  .product-art,
  .story-image {
    min-height: 210px;
  }

  .button,
  .form-row,
  .form-row .button {
    width: 100%;
  }

  .site-footer ul {
    justify-content: flex-start;
  }
}
