const { chromium } = require('/tmp/north-thread-a11y/node_modules/playwright');
const path = require('path');

async function scan(page) {
  await page.addScriptTag({ path: '/tmp/north-thread-a11y/node_modules/axe-core/axe.min.js' });
  const results = await page.evaluate(async () => window.axe.run());
