}

(async () => {
  const browser = await chromium.launch();
  const desktop = await browser.newPage({ viewport: { width: 1366, height: 900 } });
  await desktop.goto('file://' + path.resolve('index.html'), { waitUntil: 'load' });
  const desktopWcag = await scan(desktop);
  await desktop.close();

  const mobile = await browser.newPage({ viewport: { width: 320, height: 900 } });
  await mobile.goto('file://' + path.resolve('index.html'), { waitUntil: 'load' });
  const mobileWcag = await scan(mobile);
  const horizontalOverflow = await mobile.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth);
  await mobile.click('.nav-toggle');
  const mobileNavExpanded = await mobile.getAttribute('.nav-toggle', 'aria-expanded');
  await mobile.click('[data-product="Linen Chore Jacket"]');
  const cartStatus = await mobile.textContent('#cart-status');
  await mobile.close();
  await browser.close();

  const result = { desktopWcag, mobileWcag, horizontalOverflow, mobileNavExpanded, cartStatus };
  console.log(JSON.stringify(result, null, 2));
  process.exit(desktopWcag.length || mobileWcag.length || horizontalOverflow || mobileNavExpanded !== 'true' || !cartStatus.includes('Linen Chore Jacket added') ? 1 : 0);
})().catch(error => {
  console.error(error.message);
  process.exit(2);
});
