   const productName = button.dataset.product;
   button.setAttribute("aria-label", `Add to bag: ${productName}`);

   button.addEventListener("click", () => {
     bagCount += 1;
     cartCount.textContent = String(bagCount);
     cartStatus.textContent = `${productName} added to your shopping bag. ${bagCount} ${bagCount === 1 ? "item" : "items"} in bag.`;
