          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        .site-header,
        .hero-copy,
        .hero-panel,
        .deal-card,
        .newsletter,
        .product-card {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        .brand-mark,
        .cart-count,
        .button {
          forced-color-adjust: none;
        }
      }

      @media (max-width: 920px) {
        .header-inner {
          grid-template-columns: auto auto auto;
          justify-content: space-between;
        }

        .nav-toggle {
          display: inline-flex;
          align-items: center;
          gap: 0.55rem;
          min-height: 44px;
          border: 1px solid var(--border);
          border-radius: 999px;
          background: #fff;
          color: var(--ink);
          padding: 0.55rem 0.85rem;
          font-weight: 850;
        }

        .nav-toggle-lines,
        .nav-toggle-lines::before,
        .nav-toggle-lines::after {
          display: block;
          width: 18px;
          height: 2px;
          border-radius: 999px;
          background: currentColor;
        }

        .nav-toggle-lines {
          position: relative;
        }

        .nav-toggle-lines::before,
        .nav-toggle-lines::after {
          position: absolute;
          content: "";
          left: 0;
        }

        .nav-toggle-lines::before {
          top: -6px;
        }

        .nav-toggle-lines::after {
          top: 6px;
        }

        .primary-nav {
          grid-column: 1 / -1;
          width: 100%;
        }

        .primary-nav[data-collapsed] {
          display: none;
        }

        .primary-nav ul {
          flex-direction: column;
          align-items: stretch;
          padding: 0 0 1rem;
        }

        .primary-nav a {
          display: block;
          padding: 0.65rem 0;
        }

        .hero,
        .newsletter {
          grid-template-columns: 1fr;
        }

        .product-grid,
        .deal-grid,
        .editorial-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        .story-card-large {
          grid-column: span 2;
        }
      }

      @media (max-width: 640px) {
        .header-inner,
        main,
        .site-footer {
          width: min(calc(100% - 1rem), var(--max-width));
        }

        .header-inner {
          gap: 0.75rem;
          min-height: 68px;
